#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);
    // Validate conversion: must consume entire argument and not be empty
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Denominator must not be zero
    if (b == 0) {
        puts("BAD_INPUT");
        return 0;
    }
    // Range check (absolute value must be <= 100000)
    if (llabs(a) > 100000L || llabs(b) > 100000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long num = a;
    long den = b;
    long terms[200];
    int count = 0;

    while (den != 0) {
        long q = num / den;               // integer division truncates toward zero
        terms[count++] = q;
        long r = num - q * den;           // remainder
        num = den;
        den = r;
        if (count > 199) {                // safety limit
            puts("ERROR");
            return 0;
        }
    }

    // Output in the form [a0; a1, a2, ...]
    putchar('[');
    for (int i = 0; i < count; ++i) {
        printf("%ld", terms[i]);
        if (i == 0 && count > 1) {
            printf("; ");
        } else if (i < count - 1) {
            printf(", ");
        }
    }
    puts("]");
    return 0;
}
